import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { useEffect } from 'react'
import { Text, TextInput, ViewStyle } from 'react-native'
import Animated from 'react-native-reanimated'

const EMAIL_INPUT_PLACEHOLDER = 'Email address'

interface EmailInputProps {
	emailInputRef: React.RefObject<TextInput | null>
	errorShakeStyle: ViewStyle
	isEmailValid: boolean
	emailInput: string
	setEmailInput: (emailInput: string) => void
	emailError: string
}

export const EmailInputContainer = ({
	emailInputRef,
	errorShakeStyle,
	isEmailValid,
	emailInput,
	setEmailInput,
	emailError
}: EmailInputProps) => {
	const { theme, isDark } = useTheme()

	useEffect(() => {
		if (emailInputRef.current) {
			emailInputRef.current.focus()
		}
	}, [emailInputRef])

	return (
		<Animated.View style={[styles.emailInputContainer, errorShakeStyle]}>
			<TextInput
				ref={emailInputRef}
				style={[
					styles.emailInput(theme),
					emailInput && styles.emailInputIsNotEmpty(theme),
					isEmailValid && styles.validEmailInput(theme, isDark),
					!!emailError && styles.invalidEmailInput(theme)
				]}
				keyboardType="email-address"
				placeholder={EMAIL_INPUT_PLACEHOLDER}
				placeholderTextColor={colors[theme].gray[400]}
				value={emailInput}
				onChangeText={setEmailInput}
			/>
			<Text style={styles.emailErrorText(theme)}>{emailError}</Text>
		</Animated.View>
	)
}

const styles = defineStyles({
	emailInputContainer: {
		gap: 12
	},
	emailErrorText: (theme: Theme) => ({
		color: colors[theme].red[600],
		marginLeft: 20,
		fontWeight: '500',
		fontSize: 16
	}),
	emailInput: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[50],
		borderRadius: 18,
		height: 56,
		paddingHorizontal: 20,
		fontSize: 16,
		color: colors[theme].gray[600],
		fontWeight: '500',
		borderWidth: 1,
		borderColor: 'transparent'
	}),
	emailInputIsNotEmpty: (theme: Theme) => ({
		borderColor: colors[theme].gray[500]
	}),
	validEmailInput: (theme: Theme, isDark: boolean) => ({
		backgroundColor: isDark ? colors[theme].blue[300] : colors[theme].blue[50],
		color: isDark ? colors[theme].gray[900] : colors[theme].blue[700],
		borderColor: isDark ? colors[theme].gray[500] : colors[theme].blue[600]
	}),
	invalidEmailInput: (theme: Theme) => ({
		backgroundColor: colors[theme].red[50],
		color: colors[theme].red[600],
		borderWidth: 1,
		borderColor: colors[theme].red[600]
	})
})
